import{_ as t,a,b as r,c as i}from"./chunks/image-20261116061532792.C1j-yP-O.js";import{_ as s,o as n,c as o,a2 as d}from"./chunks/framework.CmPiTyN0.js";const b=JSON.parse('{"title":"Support Equipment","description":"","frontmatter":{"title":"Support Equipment","outline":"deep"},"headers":[],"relativePath":"en/wiki/equipment.md","filePath":"en/wiki/equipment.md","lastUpdated":1794811249000}'),p={name:"en/wiki/equipment.md"};function m(u,e,l,c,g,h){return n(),o("div",null,[...e[0]||(e[0]=[d('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_6-support-equipment" tabindex="-1">6. Support Equipment <a class="header-anchor" href="#_6-support-equipment" aria-label="Permalink to &quot;6. Support Equipment&quot;">​</a></h2><p>RVP support equipment is configured by bone module and has independent durability and functional state. Destroyed equipment stops working and can be restored by repair.</p><table tabindex="0"><thead><tr><th>Equipment</th><th>Function</th></tr></thead><tbody><tr><td>ERA</td><td>High damage-reduction multiplier; explodes and disappears after absorbing enough damage</td></tr><tr><td>APS</td><td>Detects and intercepts incoming ammunition by sector; if a sensor bone is destroyed, that sector stops intercepting</td></tr><tr><td>Active ECM</td><td>Jams radar/satellite/radio-guided missiles in range and becomes the strongest radiation source, attracting anti-radiation missiles. Powerful ECM on electronic-warfare aircraft can generate false signals that interfere with fighter radar and RWR</td></tr><tr><td>Passive ECM</td><td>Generates false targets when illuminated by enemy radar; stops when the bone is destroyed</td></tr><tr><td>Electro-optical jammer</td><td>Jams SACLOS missiles entering its sector, making them deviate</td></tr><tr><td>DIRCM</td><td>Directional infrared countermeasure against IR, AIR, man-in-the-loop missiles, and SBW&#39;s SA18; limited engagement channels can be saturated by multiple incoming IR missiles</td></tr><tr><td>Flares/chaff/smoke</td><td>Configured per vehicle with independent ammunition and cooldowns; flares decoy IR/AIR missiles, chaff decoys radar-guided missiles and breaks radar locks, smoke blocks laser spots and IR seekers</td></tr><tr><td>Maintenance equipment</td><td>Repairs parts and equipment</td></tr></tbody></table><p>The equipment panel shows support-equipment status and lets you set repair order. ERA and other support equipment use separate repair queues; when a bone has both ERA and another device, they recover together in the ERA queue.</p><p><img src="'+t+'" alt="image-20261116060711636"></p><p><strong>Figure 6.1 Explosive reactive armor.</strong></p><p><img src="'+a+'" alt="image-20261116060854988"></p><p><strong>Figure 6.2 Active protection system.</strong></p><p><img src="'+r+'" alt="image-20261116061357053"></p><p><strong>Figure 6.3 DIRCM jamming.</strong></p><p><img src="'+i+'" alt="image-20261116061532792"></p><p><strong>Figure 6.4 DIRCM jamming an SBW missile.</strong></p><hr>',14)])])}const q=s(p,[["render",m]]);export{b as __pageData,q as default};
